// Reproducible legacy schema fixture, generated by the actual 0.1.0 application.
import { _electron as electron } from "@playwright/test";
import { mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";
import { DatabaseSync } from "node:sqlite";
import { extractFile } from "@electron/asar";
const archive = resolve(
  process.argv[2] || "release/win-unpacked/resources/app.asar",
);
if (JSON.parse(extractFile(archive, "package.json")).version !== "0.1.0")
  throw new Error("Requires the preserved genuine 0.1.0 application ASAR");
const dir = mkdtempSync(join(tmpdir(), "pos-legacy-"));
const app = await electron.launch({
  args: [archive, "--no-sandbox", "--ozone-platform=headless", "--disable-gpu"],
  env: {
    ...process.env,
    POS_TEST_DATA_DIR: dir,
    XDG_CACHE_HOME: join(dir, "cache"),
  },
  timeout: 30000,
});
try {
  const page = await app.firstWindow();
  await page.waitForFunction(() => !!window.pos);
  const response = await page.evaluate(async () => {
    const setup = await window.pos.call("setup", {
      username: "legacy-owner",
      password: "legacy-test-password",
    });
    if (!setup.ok) throw new Error(setup.error);
    await window.pos.call("contact", {
      name: "Legacy fixture customer",
      kind: "customer",
    });
    await window.pos.call("rate", {
      from: "USD",
      to: "MMK",
      numerator: 20,
      denominator: 1,
      source: "Legacy minor-unit reference",
    });
    const item = await window.pos.call("accessory", {
      sku: "LEGACY",
      name: "Legacy fixture cable",
      category: "Cable",
      cost: 20,
      price: 100,
      currency: "MMK",
      quantity: 3,
      reorder: 0,
      method: "Cash",
    });
    if (!item.ok) throw new Error(item.error);
    const sale = await window.pos.call("sale", {
      request: crypto.randomUUID(),
      currency: "MMK",
      contactId: 1,
      items: [{ kind: "accessory", id: item.data, price: 100, quantity: 3 }],
      payments: [{ amount: 300, method: "Cash" }],
    });
    if (!sale.ok) throw new Error(sale.error);
    const returned = await window.pos.call("return", {
      request: crypto.randomUUID(),
      id: sale.data,
      refund: 100,
      reason: "Legacy fixture partial return",
      method: "Cash",
      items: [{ saleItem: 1, quantity: 1, restock: true }],
    });
    if (!returned.ok) throw new Error(returned.error);
    return true;
  });
  if (!response) throw new Error("Legacy fixture workflow failed");
} finally {
  await app.close();
}
try {
  const db = new DatabaseSync(join(dir, "business.sqlite"));
  if (db.prepare("PRAGMA user_version").get().user_version !== 7)
    throw new Error("Unexpected legacy schema");
  const tables = db
    .prepare(
      "SELECT name,sql FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name",
    )
    .all();
  const sql = [
    "-- Fixture generated by the genuine 0.1.0 Electron application. Synthetic test data only.",
    "PRAGMA foreign_keys=OFF;",
  ];
  const literal = (value) =>
    value === null
      ? "NULL"
      : typeof value === "number"
        ? String(value)
        : "'" + String(value).replaceAll("'", "''") + "'";
  for (const table of tables) {
    sql.push(table.sql + ";");
    for (const row of db.prepare(`SELECT * FROM ${table.name}`).all())
      sql.push(
        `INSERT INTO ${table.name} VALUES(${Object.values(row).map(literal).join(",")});`,
      );
  }
  sql.push("PRAGMA user_version=7;", "PRAGMA foreign_keys=ON;");
  writeFileSync("tests/fixtures/legacy-v7.sql", sql.join("\n") + "\n");
  db.close();
  console.log(
    "Captured schema 7 with a paid invoice, partial refund and legacy rate.",
  );
} finally {
  rmSync(dir, { recursive: true, force: true });
}
